    BrMatrix34ApplyV(&world_direction, pDirection, pTransform);
    scaled_random_direction.v[0] = pRandom_direction->v[0] * gPed_spurt_seed_scale;
    scaled_random_direction.v[1] = pRandom_direction->v[1] * gPed_spurt_seed_scale;
